modules.facet_nas:
"""The NAS facet — the conduit the school's comms signal propagates through.

One plane, matching 45's `iris/comms` layout so every node interoperates:

    <root>/to-<node>/<ts>-<from>-<id>.json    a node's inbox (anyone writes here to reach it)
    <root>/seen-<node>/<id>                    that node's dedup markers (consumed = touched)

`root` is the shared `_comms/` dir on the NAS. A node writes to a recipient's `to-<peer>/` inbox
(broadcast `*` fans out to every known peer) and reads its own `to-<self>/`, skipping ids already
in `seen-<self>/`. Atomic writes (tmp+rename); nothing is deleted on read (durable transcript).
Stdlib-only — a pupil Pi runs it on stock Python 3.9.
"""
from __future__ import annotations

import os
from pathlib import Path
from typing import List, Optional

from .message import Message


class NasFacet:
    def __init__(self, root, node: str):
        self.root = Path(root)
        self.node = str(node)
        self.inbox = self.root / f"to-{self.node}"
        self.seen = self.root / f"seen-{self.node}"

    def ensure_plane(self, peers: List[str]) -> None:
        self.inbox.mkdir(parents=True, exist_ok=True)
        self.seen.mkdir(parents=True, exist_ok=True)
        for p in peers:
            (self.root / f"to-{p}").mkdir(parents=True, exist_ok=True)

    def put(self, msg: Message, peers: Optional[List[str]] = None) -> Message:
        targets = [p for p in (peers or []) if p != self.node] if msg.to == "*" else [msg.to]
        for t in targets:
            d = self.root / f"to-{t}"
            d.mkdir(parents=True, exist_ok=True)
            fn = msg.wire_filename()
            dst, tmp = d / fn, d / (fn + ".tmp")
            tmp.write_text(msg.to_json(), encoding="utf-8")
            os.replace(tmp, dst)                       # atomic publish
        return msg

    def poll(self, *, advance: bool = True) -> List[Message]:
        """Inbound messages for this node not yet seen, oldest-first. `advance` marks them seen."""
        out: List[Message] = []
        if not self.inbox.is_dir():
            return out
        self.seen.mkdir(parents=True, exist_ok=True)
        for f in sorted(self.inbox.glob("*.json")):
            try:
                msg = Message.from_json(f.read_text(encoding="utf-8"))
            except Exception:
                continue
            if (self.seen / msg.id).exists():
                continue
            out.append(msg)
            if advance:
                try:
                    (self.seen / msg.id).write_text("", encoding="utf-8")
                except OSError:
                    pass
        out.sort(key=lambda m: m.ts)
        return out

    def transcript(self, nodes: List[str]) -> List[Message]:
        """Every message on the plane (all inboxes), oldest-first — the full record."""
        seen_ids, allm = set(), []
        for n in nodes:
            d = self.root / f"to-{n}"
            if not d.is_dir():
                continue
            for f in sorted(d.glob("*.json")):
                try:
                    m = Message.from_json(f.read_text(encoding="utf-8"))
                except Exception:
                    continue
                if m.id in seen_ids:
                    continue
                seen_ids.add(m.id)
                allm.append(m)
        allm.sort(key=lambda m: m.ts)
        return allm

modules.message:
"""The message — the signal on the school's comms plane.

One plane for all four nodes. This speaks the same wire form as 45's `iris/comms`
(`_comms/to-<peer>/` + `seen-<self>/`), so 45's native ember loop and the lightweight guardian CLI
here interoperate on one plane. Wire keys: `id, from, to, ts, kind, subject, body, ref`. `ts` is a
UTC ISO-8601 string. Stdlib-only, so a pupil Pi runs it on its stock Python 3.9 before its full
ember (Python 3.11) is even built.
"""
from __future__ import annotations

import json
import re
import hashlib
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Optional, Dict


def _now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _short_id(frm: str, to: str, ts: str, subject: str, body: str) -> str:
    """Content-addressed short id = de-dup key (same message re-dropped = same id)."""
    h = hashlib.sha256("\n".join((frm, to, ts, subject, body)).encode("utf-8")).hexdigest()
    return h[:12]


@dataclass
class Message:
    frm: str                                  # sending node id ("71","45","59","60")
    to: str                                   # recipient node id, or "*" broadcast
    body: str
    kind: str = "note"                        # note | ack | query | answer | lesson | alert
    subject: str = ""
    ref: Optional[str] = None                 # in-reply-to id
    ts: str = field(default_factory=_now_iso)
    id: str = ""                              # filled from content if empty

    def __post_init__(self):
        if not self.id:
            self.id = _short_id(self.frm, self.to, self.ts, self.subject, self.body)

    def to_wire(self) -> Dict:
        return {"id": self.id, "from": self.frm, "to": self.to, "ts": self.ts,
                "kind": self.kind, "subject": self.subject, "body": self.body, "ref": self.ref}

    def to_json(self) -> str:
        return json.dumps(self.to_wire(), ensure_ascii=False, indent=2)

    @staticmethod
    def from_wire(w: Dict) -> "Message":
        return Message(frm=str(w.get("from")), to=str(w.get("to")), body=str(w.get("body") or ""),
                       kind=str(w.get("kind") or "note"), subject=str(w.get("subject") or ""),
                       ref=w.get("ref"), ts=str(w.get("ts") or _now_iso()), id=str(w.get("id") or ""))

    @staticmethod
    def from_json(text: str) -> "Message":
        return Message.from_wire(json.loads(text))

    def wire_filename(self) -> str:
        ts = re.sub(r"[^0-9TZ]", "", self.ts) or "00000000T000000Z"
        return "%s-%s-%s.json" % (ts, self.frm, self.id)

    def for_node(self, node: str) -> bool:
        return self.to == node or self.to == "*"

    def one_line(self) -> str:
        subj = f" [{self.subject}]" if self.subject else ""
        return f"{self.frm}->{self.to} {self.kind}{subj}: {self.body[:80]}"
